#nullable enable
using Marten;
using Microsoft.AspNetCore.Mvc;
using Wolverine.Http;
using HourBooking.Contracts;
using HourBooking.Views;

namespace HourBooking.Slices.Booking;

/// <summary>
/// In Wolverine's aggregate handler workflow the ENDPOINT is the decider: it receives the folded
/// state and returns events. So every rule whose GIVEN names prior events lives here, where the
/// stream is visible. The two rules that need nothing but the request are in BookHoursValidator and
/// have already rejected the call before this runs.
///
/// The state is fetched explicitly rather than with [Aggregate]. That attribute resolves a stream id
/// from a single route argument, and this stream is keyed by a COMPOSITE (employeeId + month), so
/// there is no one argument for it to find. FetchForWriting gives the same optimistic-concurrency
/// guarantee and the same live fold, and it is honest about the composite key.
/// </summary>
public static class BookHoursEndpoint
{
    [WolverinePost("/timesheet/{employeeId}/{month}/bookings")]
    public static async Task<IResult> Book(
        Guid employeeId,
        string month,
        BookHours command,
        IDocumentSession session,
        CancellationToken cancellation)
    {
        // MonthIsClosed. MonthClosed lives in the MonthClosure stream, not this one, so it is a
        // cross-stream READ — never a second write. One command, one stream: a command that wrote to
        // both would need a transactional boundary around two aggregates, which the little book
        // rules out and swimlane/command-crosses-swimlane enforces.
        var gate = await session.Events.FetchLatest<MonthGate>(
            MonthGate.StreamKey(employeeId, month), cancellation);
        if (gate?.IsClosed == true)
            return Problem("MonthIsClosed", "A closed month cannot be booked into. Closed is closed.");

        // NotAProjectMember. Membership is seeded from outside this system, so it is read from the
        // MyProjects view rather than from a stream we own.
        var member = await session.LoadAsync<MyProjects>(
            MyProjects.RowId(employeeId, command.ProjectId), cancellation);
        if (member is null || member.Left)
            return Problem("NotAProjectMember",
                "Hours cannot be booked to a project the employee has left, and nothing is persisted.");

        var stream = await session.Events.FetchForWriting<BookHoursState>(
            BookHoursState.StreamKey(employeeId, month), cancellation);
        var sheet = stream.Aggregate ?? new BookHoursState();

        // AlreadyBookedUseCorrection. "There may be only one HoursBooked per day+project. Booking
        // again is a Correction" — so the screen has to offer the right action, and the API has to
        // refuse the wrong one.
        if (sheet.AlreadyBooked(command.Date, command.ProjectId))
            return Problem("AlreadyBookedUseCorrection",
                "This day and project are already booked. Correct the existing booking instead.");

        // DailyCapExceeded. Enforceable here, in the transaction, only because the stream is keyed
        // per (employee, month) and therefore holds the whole day. Keyed per booking this would have
        // been a check against an eventually-consistent projection, where two concurrent bookings
        // both pass. See ANTI-PATTERNS.md #11.
        if (sheet.HoursOn(command.Date) + command.Hours > BookHoursState.DailyCap)
            return Problem("DailyCapExceeded",
                $"At most {BookHoursState.DailyCap} hours can stand for one day.");

        stream.AppendOne(new HoursBooked(
            command.BookingId, employeeId, month, command.ProjectId,
            command.Date, command.Hours, command.Note, DateTimeOffset.UtcNow));

        await session.SaveChangesAsync(cancellation);
        return Results.NoContent();
    }

    /// <summary>
    /// A rejected rule comes back as ProblemDetails, which is what Wolverine.HTTP uses for validation
    /// failures too — so a GWT with then="error: RuleName" asserts the same shape whether the rule
    /// was caught at the periphery or here. The rule's name is the machine-readable part.
    /// </summary>
    private static IResult Problem(string rule, string detail) =>
        Results.Problem(new ProblemDetails
        {
            Title = rule,
            Detail = detail,
            Status = StatusCodes.Status400BadRequest,
        });
}

/// <summary>
/// The smallest fold over the MonthClosure stream that answers this slice's question. Not "the"
/// MonthClosure aggregate — each slice folds what it needs, and all book-hours needs to know is
/// whether the month is closed.
/// </summary>
public sealed record MonthGate
{
    public string Id { get; init; } = default!;
    public int Version { get; set; }
    public bool IsClosed { get; init; }

    public static string StreamKey(Guid employeeId, string month) => $"monthClosure:{employeeId}:{month}";

    public static MonthGate Apply(BookingMonthStarted e, MonthGate current) => current with { IsClosed = false };

    /// <summary>
    /// "A submitted month is still open and can still be booked into and corrected. Only closing
    /// stops editing." So submission and rejection deliberately do not move this gate.
    /// </summary>
    public static MonthGate Apply(MonthClosureSubmitted e, MonthGate current) => current;

    public static MonthGate Apply(MonthClosureRejected e, MonthGate current) => current;

    public static MonthGate Apply(MonthClosed e, MonthGate current) => current with { IsClosed = true };
}
